sub slurp {
    my ($path) = @_;
    open my $fh, "<", $path or die "$path: $!";
    local $/;
    return <$fh>;
}

# All declarations in the whole repo (for uniqueness)
my %global_func_names; # name -> count of func decls (non-method)
my %global_method_names; # name -> count of method decls
my @internal_decls;

for my $path (@go_files) {
    next if $path =~ /_test\.go$/;
    my $src = slurp($path);
    my $pkg = "unknown";
    if ($src =~ /^package\s+(\w+)/m) { $pkg = $1; }
    my $rel = $path;
    $rel =~ s{^\Q$ROOT\E/}{};
    my $is_internal = ($path =~ m{^\Q$INTERNAL\E/}) ? 1 : 0;

    while ($src =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*(?:\[[^\]]+\])?\s*\(/mg) {
        my ($recv, $name) = ($1 // "", $2);
        $recv =~ s/^\s+|\s+$//g;
        my $is_method = ($recv ne "" ? 1 : 0);
        if ($is_method) { $global_method_names{$name}++; }
        else { $global_func_names{$name}++; }
        if ($is_internal) {
            push @internal_decls, {
                name => $name,
                recv => $recv,
                pkg => $pkg,
                path => $rel,
                is_method => $is_method,
            };
