# Split files into functions to count unique callers
# Rough: find func bodies by next func at column 0
sub extract_funcs {
    my ($src, $path) = @_;
    my @funcs;
    my @starts;
    while ($src =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)/mg) {
        push @starts, [$-[0], $2, $1 // ""];
    }
    for my $i (0 .. $#starts) {
        my $end = ($i < $#starts) ? $starts[$i+1][0] : length($src);
        my $body = substr($src, $starts[$i][0], $end - $starts[$i][0]);
        push @funcs, {
            name => $starts[$i][1],
            recv => $starts[$i][2],
            body => $body,
            path => $path,
        };
    }
    return @funcs;
