open my $lf, "<", "/tmp/gofiles.txt" or die $!;
my @files = <$lf>; chomp @files;
sub slurp { open my $fh, "<", $_[0] or die $!; local $/; <$fh> }
for my $path (@files) {
  my $src = slurp($path);
  next unless $src =~ /NewEngine\s*\(/;
  my $rel = $path; $rel =~ s{^\Q$ROOT\E/}{};
  my @starts;
  while ($src =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)/mg) {
    push @starts, [$-[0], $2];
  }
  for my $i (0 .. $#starts) {
    my $end = ($i < $#starts) ? $starts[$i+1][0] : length($src);
    my $body = substr($src, $starts[$i][0], $end - $starts[$i][0]);
    my $count = 0;
    while ($body =~ /(?<![\w.])NewEngine\s*\(/g) {
      my $start = $-[0];
      my $from = $start > 40 ? $start - 40 : 0;
      my $prefix = substr($body, $from, $start - $from);
      next if $prefix =~ /func\s+(\([^)]+\)\s+)?$/;
      $count++;
    }
    next unless $count;
    print "$count\t$rel\t$starts[$i][1]\n";
  }
}
'
