perl -e '
use strict;
my $ROOT = "/bench/repo";
open my $lf, "<", "/tmp/gofiles.txt" or die $!;
my @files = <$lf>; chomp @files;
sub slurp { open my $fh, "<", $_[0] or die $!; local $/; <$fh> }
for my $name ("schema.Field", "addArg") {
  print "--- $name ---\n";
  my $re = $name eq "addArg" ? qr/(?<![\w.])addArg\s*\(/ : qr/\.Field\s*\(/;
  for my $path (@files) {
    next if $path =~ /_test\.go$/;
    my $src = slurp($path);
    next unless $src =~ /$re/;
    my $rel = $path; $rel =~ s{^\Q$ROOT\E/}{};
    my @starts;
    while ($src =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)/mg) {
      push @starts, [$-[0], $2];
    }
    for my $i (0 .. $#starts) {
      my $end = ($i < $#starts) ? $starts[$i+1][0] : length($src);
      my $body = substr($src, $starts[$i][0], $end - $starts[$i][0]);
      my $count = () = $body =~ /$re/g;
      next unless $count;
      # skip Field declaration
      next if $starts[$i][1] eq "Field" && $name ne "addArg";
      print "$count\t$rel\t$starts[$i][1]\n";
    }
  }
}
